const probe = async (options: Options): Promise<void> => {
  if (typeof options.js !== "string") throw new Error("probe needs --js <expression>.");
  const { session } = await open(options);
  try {
    await ensureRunner(session.page);
    const value = await session.page.evaluate(async (expression) => {
      const indirect = eval;
      return JSON.parse(JSON.stringify((await indirect(expression)) ?? null));
    }, options.js);
    console.log(JSON.stringify(value, null, 2));
    await waitForSync(session.page);
  } finally {
    await session.close();
  }
};

